app.get("/jobs", async (req, res) => {
  const limit = Math.min(Number(req.query.limit) || 20, 100);
  const filter = { status: req.query.status || "open" };
  if (req.query.cursor) filter._id = { $lt: ObjectId(req.query.cursor) };

  const jobs = await db.jobs
    .find(filter)
    .sort({ _id: -1 })
    .limit(limit + 1)
    .toArray();

  const hasMore = jobs.length > limit;
  const items = hasMore ? jobs.slice(0, limit) : jobs;
  res.json({ items, nextCursor: hasMore ? String(items.at(-1)._id) : null });
});

const Joi = require("joi");

const jobSchema = Joi.object({
  title: Joi.string().trim().min(3).max(120).required(),
  salaryMin: Joi.number().integer().min(0).max(1_000_000),
  tags: Joi.array().items(Joi.string().max(30)).max(10),
  role: Joi.forbidden(), // clients may never set this
}).unknown(false);

app.post("/jobs", (req, res) => {
  const { error, value } = jobSchema.validate(req.body);
  if (error) return res.status(400).json({ error: error.message });
  res.status(201).json(createJob(value));
});

function authenticate(req, res, next) {
  const header = req.get("authorization") || "";
  const token = header.startsWith("Bearer ") ? header.slice(7) : null;
  const user = token && verifyToken(token);
  if (!user) return res.status(401).json({ error: "Unauthorized" });
  req.user = user;
  next();
}

function requireAdmin(req, res, next) {
  if (req.user.role !== "admin") {
    return res.status(403).json({ error: "Forbidden" });
  }
  next();
}

app.delete("/jobs/:id", authenticate, requireAdmin, deleteJob);

